// uart_driver.sv - generated by uvm_full_tb_generator.py, filled in with UART protocol logic
//   Acts as the PC transmitter: each item becomes an 8N1 frame on uart_rx_i
//   idle(1) .. start(0) d0 d1 .. d7 stop(1), LSB first, clks_per_bit clocks per bit.
class uart_driver extends uvm_driver #(uart_item);
virtual uart_if vif;
int unsigned clks_per_bit = 64;   // UART divisor + 1 (sim divisor 63)
`uvm_component_utils(uart_driver)
function new(string n,uvm_component p);super.new(n,p);endfunction

function void build_phase(uvm_phase phase);
  super.build_phase(phase);
  if (!uvm_config_db#(virtual uart_if)::get(this, "", "uart_vif", vif))
    `uvm_fatal("NOVIF", "uart_vif not set in uvm_config_db")
  void'(uvm_config_db#(int unsigned)::get(this, "", "uart_clks_per_bit", clks_per_bit));
endfunction

task run_phase(uvm_phase phase);
  vif.uart_rx_i <= 1'b1;                 // line idles high
  wait (vif.rst_n === 1'b1);
  forever begin
    seq_item_port.get_next_item(req);
    send_frame(req);
    `uvm_info("UART_DRV", {"sent ", req.convert2string()}, UVM_MEDIUM)
    seq_item_port.item_done();
  end
endtask

task bit_time(bit level);
  vif.uart_rx_i <= level;
  repeat (clks_per_bit) @(posedge vif.clk);
endtask

task send_frame(uart_item tr);
  bit [7:0] d = tr.data;
  if (tr.inject_err) d[tr.err_bit] = ~d[tr.err_bit];
  repeat (tr.idle_bits) bit_time(1'b1);
  bit_time(1'b0);                        // start bit
  for (int i = 0; i < 8; i++) bit_time(d[i]);
  bit_time(1'b1);                        // stop bit
endtask
endclass
